# name: agreement_sd_structurally_neutral
# description: SD across participants of the rate of agreeing with the pair majority, restricted to pairs where both sequences have equal three-flip chunk variety and neither/both are rule-built (so pattern sensitivity cannot act); observed above null means person heterogeneity in consistency persists outside pattern structure (model under-produces it there), below means it over-produces it.
def test_statistic(df):
    seqs = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    def trip(s):
        n = len(s) - 2
        return 0.0 if n < 1 else len({s[i:i+3] for i in range(n)}) / min(8, n)
    def rule(s):
        n = len(s)
        if len(set(s)) < 2:
            return 0
        for p in range(2, n // 2 + 1):
            if all(s[i] == s[i+p] for i in range(n - p)):
                return 1
        return int(s == s.translate(str.maketrans("HT", "TH"))[::-1])
    tr = {s: trip(s) for s in seqs}; ru = {s: rule(s) for s in seqs}
    m = ((df["sequence_a"].map(tr) - df["sequence_b"].map(tr)).abs() < 1e-9) & \
        (df["sequence_a"].map(ru) == df["sequence_b"].map(ru))
    d = df[m.to_numpy()]
    a = d["sequence_a"]; b = d["sequence_b"]
    first = a < b
    key = pd.Series(np.where(first, a + "|" + b, b + "|" + a), index=d.index)
    y = pd.Series(np.where(first, d["chose_left"], 1 - d["chose_left"]), index=d.index)
    rate = y.groupby(key).transform("mean")
    agree = ((y == 1) == (rate >= 0.5)).astype(float)
    per = agree.groupby(d["participant_id"]).mean()
    return float(per.std()) if len(per) > 1 else 0.0

# name: final_run_shorter_chosen
# description: Among pairs whose final runs (trailing streak) differ in length, the rate of choosing the sequence with the shorter final run; observed above null means a recency-weighted aversion to streaks at the end that the position-blind model under-produces, below means the model overstates it.
def test_statistic(df):
    def fr(col):
        s = df[col]
        last = s.str[-1]
        stripped_h = s.str.rstrip("H").str.len()
        stripped_t = s.str.rstrip("T").str.len()
        return (s.str.len() - np.where(last == "H", stripped_h, stripped_t)).to_numpy()
    fa = fr("sequence_a"); fb = fr("sequence_b")
    m = fa != fb
    if not m.any():
        return 0.5
    c = df["chose_left"].to_numpy()[m]
    return float(np.where(fa[m] < fb[m], c, 1 - c).mean())

# name: shorter_longest_run_equal_switches
# description: Among pairs with equal switch counts but different longest runs, the rate of choosing the sequence with the shorter longest run; observed above null means people penalise long streaks beyond what switch rate/span/chunks capture (model under-produces streak aversion), below means the model overstates it.
import re
def test_statistic(df):
    seqs = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    lr = {s: max(len(r) for r in re.findall(r"H+|T+", s)) for s in seqs}
    sw = {s: sum(1 for x, y in zip(s, s[1:]) if x != y) for s in seqs}
    la = df["sequence_a"].map(lr).to_numpy(); lb = df["sequence_b"].map(lr).to_numpy()
    sa = df["sequence_a"].map(sw).to_numpy(); sb = df["sequence_b"].map(sw).to_numpy()
    m = (sa == sb) & (la != lb)
    if not m.any():
        return 0.5
    c = df["chose_left"].to_numpy()[m]
    return float(np.where(la[m] < lb[m], c, 1 - c).mean())

# name: balanced_count_equal_span
# description: Among pairs with equal tally span (max-min of running H-T) but different final |#H-#T|, the rate of choosing the sequence with the more balanced final H/T count; observed above null means people use the overall H/T count beyond the span the model uses (model under-produces count balancing), below means the opposite.
def test_statistic(df):
    seqs = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    def span(s):
        t = np.cumsum([1 if ch == "H" else -1 for ch in s])
        return int(max(t.max(), 0) - min(t.min(), 0))
    sp = {s: span(s) for s in seqs}
    ia = (2 * df["sequence_a"].str.count("H") - df["sequence_a"].str.len()).abs().to_numpy()
    ib = (2 * df["sequence_b"].str.count("H") - df["sequence_b"].str.len()).abs().to_numpy()
    pa = df["sequence_a"].map(sp).to_numpy(); pb = df["sequence_b"].map(sp).to_numpy()
    m = (pa == pb) & (ia != ib)
    if not m.any():
        return 0.5
    c = df["chose_left"].to_numpy()[m]
    return float(np.where(ia[m] < ib[m], c, 1 - c).mean())
